```java
public int removeShort(int min) {
    int removed = 0;
    for (int i = songs.size() - 1; i >= 0; i--) {
        if (songs.get(i).getSeconds() < min) {
            songs.remove(i);
            removed++;
        }
    }
    return removed;
}
```

```java
public int emptyInRow(int row) {
    int count = 0;
    for (int c = 0; c < seats[row].length; c++) {
        if (seats[row][c] == 0) {
            count++;
        }
    }
    return count;
}
```

```java
public int findBlock(int k) {
    for (int r = 0; r < seats.length; r++) {
        int run = 0;
        for (int c = 0; c < seats[r].length; c++) {
            if (seats[r][c] == 0) {
                run++;
            } else {
                run = 0;
            }
            if (run >= k) {
                return r;
            }
        }
    }
    return -1;
}
```
